17	package org.apache.camel.component.platform.http.vertx;
18	
19	import java.io.PipedInputStream;
20	import java.io.PipedOutputStream;
21	import java.nio.charset.StandardCharsets;
22	import java.util.concurrent.CompletableFuture;
23	import java.util.concurrent.CountDownLatch;
24	import java.util.concurrent.TimeUnit;
25	import java.util.concurrent.atomic.AtomicReference;
26	
27	import io.vertx.core.http.HttpClient;
28	import io.vertx.core.http.HttpMethod;
29	import org.apache.camel.CamelContext;
30	import org.apache.camel.Exchange;
31	import org.apache.camel.builder.RouteBuilder;
32	import org.junit.jupiter.api.Test;
33	
34	import static org.junit.jupiter.api.Assertions.assertEquals;
35	import static org.junit.jupiter.api.Assertions.assertTrue;
36	
37	public class VertxPlatformHttpSseTest {
38	
39	    @Test
40	    void testSseEventsDeliveredEagerly() throws Exception {
41	        final CamelContext context = VertxPlatformHttpEngineTest.createCamelContext();
42	
43	        // Writer waits on this latch after sending event-1.
44	        // If event-1 is flushed eagerly, the client reads it and counts down,
45	        // unblocking the writer to send event-2.
46	        // If events are batched, the client never sees event-1 until the stream
47	        // closes, so the latch times out and the test fails.
48	        CountDownLatch event1Received = new CountDownLatch(1);
49	        AtomicReference<Throwable> writerError = new AtomicReference<>();
50	
51	        HttpClient client = null;
52	        try {
53	            context.addRoutes(new RouteBuilder() {
54	                @Override
55	                public void configure() {
56	                    from("platform-http:/sse")
57	                            .process(exchange -> {
58	                                PipedOutputStream out = new PipedOutputStream();
59	                                PipedInputStream in = new PipedInputStream(out);
60	
61	                                exchange.getMessage().setHeader(Exchange.CONTENT_TYPE, "text/event-stream");
62	                                exchange.getMessage().setBody(in);
63	
64	                                Thread writer = new Thread(() -> {
65	                                    try {
66	                                        out.write("data: event-1\n\n".getBytes(StandardCharsets.UTF_8));
67	                                        out.flush();
68	
69	                                        assertTrue(event1Received.await(5, TimeUnit.SECONDS),
70	                                                "Client did not receive event-1 before timeout — events may be buffered");
71	
72	                                        out.write("data: event-2\n\n".getBytes(StandardCharsets.UTF_8));
73	                                        out.flush();
74	                                        out.close();
75	                                    } catch (Throwable e) {
76	                                        writerError.set(e);
77	                                        try {
78	                                            out.close();
79	                                        } catch (Exception ignored) {
80	                                        }
81	                                    }
82	                                });
83	                                writer.setDaemon(true);
84	                                writer.start();
85	                            });
86	                }
87	            });
88	
89	            VertxPlatformHttpEngineTest.startCamelContext(context);
90	
91	            VertxPlatformHttpServer server = context.hasService(VertxPlatformHttpServer.class);
92	            client = server.getVertx().createHttpClient();
93	
94	            StringBuilder received = new StringBuilder();
95	            CompletableFuture<Void> streamDone = new CompletableFuture<>();
96	
97	            client.request(HttpMethod.GET, server.getPort(), "localhost", "/sse")
98	                    .onSuccess(request -> {
99	                        request.response()
100	                                .onSuccess(response -> {
101	                                    assertEquals(200, response.statusCode());
102	                                    assertEquals("text/event-stream", response.getHeader("Content-Type"));
103	
104	                                    response.handler(buffer -> {
105	                                        String chunk = buffer.toString(StandardCharsets.UTF_8);
106	                                        received.append(chunk);
107	
108	                                        if (chunk.contains("event-1")) {
109	                                            event1Received.countDown();
110	                                        }
111	                                    });
112	                                    response.endHandler(v -> streamDone.complete(null));
113	                                    response.exceptionHandler(streamDone::completeExceptionally);
114	                                })
115	                                .onFailure(streamDone::completeExceptionally);
116	                        request.end();
117	                    })
118	                    .onFailure(streamDone::completeExceptionally);
119	
120	            streamDone.get(10, TimeUnit.SECONDS);
121	
122	            String[] events = received.toString().split("\n\n");
123	            assertEquals(2, events.length);
124	            assertEquals("data: event-1", events[0]);
125	            assertEquals("data: event-2", events[1]);
126	
127	            Throwable error = writerError.get();
128	            if (error != null) {
129	                throw new AssertionError("Writer thread failed", error);
130	            }
131	        } finally {
132	            if (client != null) {
133	                client.close().toCompletionStage().toCompletableFuture().get(5, TimeUnit.SECONDS);
134	            }
135	            context.stop();
136	        }
137	    }
138	}
