        try {
            context.addRoutes(new RouteBuilder() {
                @Override
                public void configure() {
                    from("platform-http:/streaming?useStreaming=true")
                            .log("Done processing request");
                }
            });

            VertxPlatformHttpEngineTest.startCamelContext(context);

            given()
                    .body(testFile.toFile())
                    .post("/streaming")
                    .then()
                    .statusCode(200)
                    .body(is(content));
        } finally {
            context.stop();
            Files.deleteIfExists(testFile);
        }
    }

    @Test
    void testPopulateOnlyHeadersWithFormUrlEncodedBody() throws Exception {
        final CamelContext context = VertxPlatformHttpEngineTest.createCamelContext();
