            given()
                    .contentType(ContentType.URLENC)
                    .formParam("foo", "bar")
                    .post("/form")
                    .then()
                    .statusCode(204)
                    .header("foo", "bar")
                    .body(is(emptyOrNullString()));
        } finally {
            context.stop();
        }
    }

    @Test
